6517	  // Compute subtotal/GST/total/deposit for a quote from its line items.
6518	  // Amounts are GST-INCLUSIVE: gst is the portion already inside the total.
6519	  function computeQuoteTotals(
6520	    lineItems: Array<{ lineTotalCents: number }>,
6521	    gstRegistered: boolean,
6522	    depositEnabled: boolean,
6523	    depositType?: string,
6524	    depositValue?: number,
6525	  ) {
6526	    const totalCents = lineItems.reduce((s, li) => s + li.lineTotalCents, 0);
6527	    const gstCents = gstRegistered ? Math.round(totalCents - totalCents / (1 + GST_RATE)) : 0;
6528	    const subtotalCents = totalCents - gstCents;
6529	    let depositCents: number | null = null;
6530	    if (depositEnabled && depositType && depositValue != null) {
6531	      depositCents = depositType === "percent"
6532	        ? Math.round(totalCents * (depositValue / 100))
6533	        : Math.min(depositValue, totalCents);
6534	    }
6535	    return { subtotalCents, gstCents, totalCents, depositCents };
6536	  }
